import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.BuUvxvtQ.js";const p=JSON.parse('{"title":"Web App Guide","description":"","frontmatter":{},"headers":[],"relativePath":"web-app.md","filePath":"web-app.md"}'),n={name:"web-app.md"};function i(s,e,d,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="web-app-guide" tabindex="-1">Web App Guide <a class="header-anchor" href="#web-app-guide" aria-label="Permalink to &quot;Web App Guide&quot;">​</a></h1><p>Sky Style combines live weather, your saved closet, and an AI recommendation in one dashboard. This guide walks through every area of the app.</p><h2 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h2><ol><li>Create an account at <a href="https://skystyle.app" target="_blank" rel="noreferrer">skystyle.app</a> by signing in with GitHub or Google.</li><li>On the dashboard, choose a location manually or permit location access.</li><li>Add the clothes you actually own in <strong>Closet</strong>.</li><li>Generate a recommendation and use follow-up questions to refine it.</li></ol><h2 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h2><p>The dashboard is split into a weather panel and a settings panel. The split is adjustable in <a href="#settings">Settings</a>.</p><h3 id="recommendation-modes" tabindex="-1">Recommendation modes <a class="header-anchor" href="#recommendation-modes" aria-label="Permalink to &quot;Recommendation modes&quot;">​</a></h3><p>Each recommendation can run at one of four complexity levels, set in the Weather Planning panel:</p><table tabindex="0"><thead><tr><th>Mode</th><th>Description</th></tr></thead><tbody><tr><td>Simple</td><td>A concise outfit suggestion.</td></tr><tr><td>Simple+</td><td>Slightly more detail.</td></tr><tr><td>Advanced</td><td>Deeper reasoning and options.</td></tr><tr><td>Pro</td><td>The most thorough recommendation.</td></tr></tbody></table><p>Your default mode is configurable in <a href="#dashboard-behaviour">Settings → Dashboard Behaviour</a>.</p><h3 id="follow-up-questions" tabindex="-1">Follow-up questions <a class="header-anchor" href="#follow-up-questions" aria-label="Permalink to &quot;Follow-up questions&quot;">​</a></h3><p>After a recommendation, ask follow-ups like &quot;should I bring an umbrella?&quot; or &quot;what if I need formal shoes?&quot;. Follow-ups run in one of two modes (set in Settings):</p><ul><li><strong>Replace mode</strong> (default) — each follow-up overwrites the current outfit suggestion.</li><li><strong>Chat mode</strong> — follow-ups append below, keeping a running conversation history.</li></ul><h3 id="bring-your-own-key-pro-dev" tabindex="-1">Bring Your Own Key (Pro &amp; Dev) <a class="header-anchor" href="#bring-your-own-key-pro-dev" aria-label="Permalink to &quot;Bring Your Own Key (Pro &amp; Dev)&quot;">​</a></h3><p>Pro and Dev users can supply their own AI provider key (OpenAI, Gemini, or Mistral) so recommendations are billed to their own account. Keys are stored only in your browser and are never sent to Sky Style servers except for the single AI request. The BYOK panel also lets you set a custom prompt that replaces the default Sky Style prompt (it must include JSON output instructions).</p><div class="tip custom-block"><p class="custom-block-title">BYOK is optional</p><p>Without a BYOK key, Sky Style uses its own AI provider according to your plan tier.</p></div><h2 id="closet" tabindex="-1">Closet <a class="header-anchor" href="#closet" aria-label="Permalink to &quot;Closet&quot;">​</a></h2><p>The <strong>Closet</strong> page (<code>/closet</code>) holds the clothes you own so the AI can tailor recommendations to your actual wardrobe. Items are returned in the order you added them. Closet usage is limited per day on the Free plan and unlimited on Pro/Dev.</p><h2 id="account" tabindex="-1">Account <a class="header-anchor" href="#account" aria-label="Permalink to &quot;Account&quot;">​</a></h2><p>The <strong>Account</strong> page (<code>/account</code>) is the hub for your profile and safety controls. It shows:</p><ul><li>Your <strong>plan badge</strong> (Free, Pro, or Dev)</li><li><strong>AI usage today</strong> against your daily limits</li><li><strong>Credits</strong> balances (Pro/Dev only)</li><li>Embedded <strong>Security</strong> and <strong>Privacy Hub</strong> sections</li></ul><p>Use it as the entry point for security settings, privacy controls, and API access.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>The <strong>Settings</strong> page (<code>/settings</code>) controls appearance, dashboard behaviour, and layout. Most preferences are stored in your browser only; only your unit preference is saved to your account.</p><h3 id="profile" tabindex="-1">Profile <a class="header-anchor" href="#profile" aria-label="Permalink to &quot;Profile&quot;">​</a></h3><p>Set the <strong>gender context</strong> used for outfit recommendations: Male, Female, Other, or a manual entry (max 30 characters). This is stored locally and never sent to Sky Style except when required for an AI request.</p><h3 id="units" tabindex="-1">Units <a class="header-anchor" href="#units" aria-label="Permalink to &quot;Units&quot;">​</a></h3><p>Switch between <strong>metric</strong> (°C, km/h) and <strong>imperial</strong> (°F, mph). This is saved to your account and applies across the dashboard and the public API.</p><h3 id="appearance" tabindex="-1">Appearance <a class="header-anchor" href="#appearance" aria-label="Permalink to &quot;Appearance&quot;">​</a></h3><ul><li><strong>Theme</strong>: system, light, or dark.</li><li><strong>Reduce motion</strong>: minimises animated weather effects and interface transitions.</li></ul><h3 id="preferences" tabindex="-1">Preferences <a class="header-anchor" href="#preferences" aria-label="Permalink to &quot;Preferences&quot;">​</a></h3><ul><li><strong>Share my location with AI</strong> — include your location in the AI prompt for more relevant recommendations.</li><li><strong>Weather only</strong> — show weather data without generating an AI outfit recommendation.</li><li><strong>Simple Mode default on Terms &amp; Privacy pages</strong> — show plain-English summaries.</li></ul><h3 id="dashboard-behaviour" tabindex="-1">Dashboard behaviour <a class="header-anchor" href="#dashboard-behaviour" aria-label="Permalink to &quot;Dashboard behaviour&quot;">​</a></h3><ul><li><strong>Weather Planning Panel</strong>: always open, closed by default, or disabled entirely.</li><li><strong>Default recommendation mode</strong>: Simple, Simple+, Advanced, or Pro.</li><li><strong>Follow-up mode</strong>: Replace or Chat (see <a href="#follow-up-questions">Dashboard</a>).</li><li><strong>Session Diagnostics</strong>: show a diagnostics panel on the dashboard.</li><li><strong>BYOK panel</strong>: expand the Bring Your Own Key section by default.</li></ul><h3 id="layout-spacing" tabindex="-1">Layout &amp; spacing <a class="header-anchor" href="#layout-spacing" aria-label="Permalink to &quot;Layout &amp; spacing&quot;">​</a></h3><ul><li><strong>Dashboard layout</strong>: Symmetrical Split, Large Weather (default), or Large Settings — with a live preview.</li><li><strong>Extra Side Spacing</strong>: add horizontal padding to selected pages (dashboard, account, settings, closet, feedback, inbox, automatic recommendations).</li><li><strong>Custom Column Spacing</strong>: when on, drag the divider between dashboard panels to resize them freely. The ratio is saved automatically.</li></ul><h3 id="tutorials" tabindex="-1">Tutorials <a class="header-anchor" href="#tutorials" aria-label="Permalink to &quot;Tutorials&quot;">​</a></h3><p>Replay any guided tour whenever you need a refresher:</p><ul><li>Dashboard tour</li><li>API Dashboard tour</li><li>Dev Dashboard tour</li></ul><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><p>The <strong>Security</strong> page (<code>/settings/security</code>) protects your account. It is also embedded in the Account page.</p><h3 id="two-factor-authentication-2fa" tabindex="-1">Two-factor authentication (2FA) <a class="header-anchor" href="#two-factor-authentication-2fa" aria-label="Permalink to &quot;Two-factor authentication (2FA)&quot;">​</a></h3><p>Add a TOTP authenticator (Google Authenticator, Authy, or Bitwarden) for an extra sign-in factor:</p><ol><li>Scan the QR code with your authenticator app.</li><li>Enter the 6-digit code to verify and enable.</li><li>Save your <strong>recovery codes</strong> — they are shown only once. Download them as <code>skystyle-recovery-codes.txt</code> and keep them safe. Each code can be used once.</li></ol><p>You can <strong>regenerate</strong> recovery codes at any time (which invalidates the old ones) and disable 2FA by confirming a current code.</p><h3 id="passkeys" tabindex="-1">Passkeys <a class="header-anchor" href="#passkeys" aria-label="Permalink to &quot;Passkeys&quot;">​</a></h3><p>Sign in with <strong>Face ID, Touch ID, Windows Hello, or a hardware security key</strong>. Register a passkey with a custom name (e.g. &quot;iPhone&quot;), then list or remove registered passkeys.</p><h3 id="api-keys" tabindex="-1">API keys <a class="header-anchor" href="#api-keys" aria-label="Permalink to &quot;API keys&quot;">​</a></h3><p>Create and revoke API keys for <a href="./api/">public API</a> access:</p><ul><li>Keys are prefixed with <code>sk_live_</code> and shown <strong>only once</strong> at creation — copy immediately.</li><li>View active and revoked keys with their creation date.</li><li>Revoke any key instantly.</li></ul><div class="tip custom-block"><p class="custom-block-title">Full key management</p><p>The <a href="#api-dashboard">API Dashboard</a> offers richer key management — nicknames, folders, and credit allocation.</p></div><h3 id="security-log" tabindex="-1">Security log <a class="header-anchor" href="#security-log" aria-label="Permalink to &quot;Security log&quot;">​</a></h3><p>An auditable log of security events on your account, including sign-ins, passkey and MFA changes, API key changes, deletion requests, and data exports. Each entry shows the event, the originating IP, and a timestamp.</p><h2 id="privacy-hub" tabindex="-1">Privacy Hub <a class="header-anchor" href="#privacy-hub" aria-label="Permalink to &quot;Privacy Hub&quot;">​</a></h2><p>The <strong>Privacy Hub</strong> (<code>/settings/privacy</code>) controls your data. It is also embedded in the Account page.</p><h3 id="data-export" tabindex="-1">Data export <a class="header-anchor" href="#data-export" aria-label="Permalink to &quot;Data export&quot;">​</a></h3><p>Download everything Sky Style stores about you — your profile, settings, closet, usage history, feedback, and security logs — as a structured JSON file (human-readable and machine-parseable, with a version stamp and export timestamp).</p><p>Exports are rate-limited: non-Dev accounts can request one export every <strong>12 hours</strong>.</p><h3 id="account-deletion" tabindex="-1">Account deletion <a class="header-anchor" href="#account-deletion" aria-label="Permalink to &quot;Account deletion&quot;">​</a></h3><p>Request permanent deletion of your account and all associated data. This is a <strong>human-reviewed process</strong> — a developer actions it within 7 days. Until then, you can cancel at any time from the Privacy Hub or the banner shown on the dashboard. An optional reason (max 1000 characters) helps improve Sky Style.</p><h2 id="automatic-recommendations" tabindex="-1">Automatic recommendations <a class="header-anchor" href="#automatic-recommendations" aria-label="Permalink to &quot;Automatic recommendations&quot;">​</a></h2><p>The <strong>Automatic recommendations</strong> page (<code>/automatic-recommendations</code>) schedules an exact-time outfit recommendation using a manual location. Each schedule includes:</p><ul><li>A <strong>label</strong> (e.g. &quot;Morning commute&quot;)</li><li><strong>Latitude and longitude</strong> (manual — GPS is not used)</li><li>A <strong>run time</strong> and <strong>recurrence</strong> (once, daily, or weekly)</li><li>A <strong>unit preference</strong> (metric or imperial)</li><li>Your <strong>timezone</strong> (detected automatically)</li><li>An optional <strong>styling prompt</strong> (max 1000 characters)</li></ul><p>Schedules can be paused and resumed. Recent results show the status, time, and the saved outfit (or any error). Completed recommendations are also delivered to your <strong>Inbox</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Scheduling</p><p>The scheduler runs via Supabase Cron and invokes the secure worker each minute, so exact-time recommendations are delivered at the minute you schedule.</p></div><h2 id="api-dashboard" tabindex="-1">API Dashboard <a class="header-anchor" href="#api-dashboard" aria-label="Permalink to &quot;API Dashboard&quot;">​</a></h2><p>The <strong>API Dashboard</strong> (<code>/dashboard/api</code>) is the full key-management surface for the <a href="./api/">public API</a>:</p><ul><li><strong>Create and revoke</strong> <code>sk_live_</code> API keys (shown only once at creation).</li><li><strong>Name and group</strong> keys with nicknames and folders.</li><li><strong>Allocate</strong> <code>$ Credit</code> (AUD) to a specific key, converting $1.00 into 50 API Credit.</li><li>View per-key balances.</li></ul><table tabindex="0"><thead><tr><th>Plan</th><th>Active keys</th></tr></thead><tbody><tr><td>Free</td><td>3</td></tr><tr><td>Pro</td><td>20</td></tr><tr><td>Dev</td><td>Unlimited</td></tr></tbody></table><p>See <a href="./api/errors.html">Errors &amp; Credits</a> for how credits are charged and the App Credit fallback.</p><h2 id="feedback" tabindex="-1">Feedback <a class="header-anchor" href="#feedback" aria-label="Permalink to &quot;Feedback&quot;">​</a></h2><p>The <strong>Feedback</strong> page (<code>/feedback</code>) lets signed-in users share a bug report, suggestion, or message. Pro and Dev context is passed along automatically. Your past submissions are tracked as <strong>tickets</strong> you can review on the same page.</p><h2 id="inbox" tabindex="-1">Inbox <a class="header-anchor" href="#inbox" aria-label="Permalink to &quot;Inbox&quot;">​</a></h2><p>The <strong>Inbox</strong> keeps recommendation, support, system, and changelog notices together in one place. Automatic recommendation results are delivered here, and unread counts surface across the app.</p><h2 id="credits" tabindex="-1">Credits <a class="header-anchor" href="#credits" aria-label="Permalink to &quot;Credits&quot;">​</a></h2><p>Sky Style keeps three balances distinct:</p><table tabindex="0"><thead><tr><th>Balance</th><th>Use</th></tr></thead><tbody><tr><td>$ Credit (AUD)</td><td>Convert $1.00 into 50 API Credit for a key you choose. Pro receives $1.00 each calendar month.</td></tr><tr><td>API Credit</td><td>Per-key balance consumed by public API requests.</td></tr><tr><td>App Credit</td><td>In-app balance, including developer gifts and API fallback when a key&#39;s API Credit is empty. Pro receives 50 App Credits each day.</td></tr></tbody></table><p>API credit purchases are not live yet; the app&#39;s donation prompt is intentionally informational.</p><h2 id="plans" tabindex="-1">Plans <a class="header-anchor" href="#plans" aria-label="Permalink to &quot;Plans&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Free</th><th>Pro</th></tr></thead><tbody><tr><td>AI uses</td><td>20/day</td><td>50 App Credits/day</td></tr><tr><td>Follow-ups</td><td>40/day</td><td>400/day</td></tr><tr><td>Closet</td><td>4 uses/day</td><td>Unlimited</td></tr><tr><td>Source picker</td><td>4/day</td><td>Unlimited</td></tr><tr><td>BYOK AI key</td><td>—</td><td>✅</td></tr><tr><td>Custom prompts</td><td>—</td><td>✅</td></tr></tbody></table><p>The <strong>Dev</strong> tier bypasses all limits and is only provisioned to developer accounts. The <strong>Demo</strong> tier is created automatically in preview/development environments and multiplies the free limits by 10 for testing.</p><h2 id="help-and-service-status" tabindex="-1">Help and service status <a class="header-anchor" href="#help-and-service-status" aria-label="Permalink to &quot;Help and service status&quot;">​</a></h2><p>Use the app Inbox or Feedback page for account help. API users should consult the <a href="./api/errors.html">API error guide</a> and the <a href="https://status.coolmanyt.com/" target="_blank" rel="noreferrer">COOLman service status page</a> for service and downtime information. Monitoring integrations can use its <a href="https://status.coolmanyt.com/v3/components.json" target="_blank" rel="noreferrer">live component status JSON</a>.</p>',83)])])}const m=t(n,[["render",i]]);export{p as __pageData,m as default};
